-- Sinh tự động bằng scripts/gen_dbt_staging.py từ conf/schema/perf.yml, đừng sửa tay.
-- Ép kiểu và đổi mã thiếu thành null; giá trị đã qua cổng chất lượng nên ép kiểu không lỗi.
SELECT
    CASE WHEN TRIM(loan_id) IN ('') THEN NULL ELSE TRIM(loan_id) END AS loan_id,
    CASE WHEN TRIM(reporting_period) IN ('') THEN NULL ELSE TRIM(reporting_period) END AS reporting_period,
    CAST(CASE WHEN TRIM(current_upb) IN ('') THEN NULL ELSE TRIM(current_upb) END AS DECIMAL(20, 4)) AS current_upb,
    CASE WHEN TRIM(delinquency_status) IN ('', 'XX') THEN NULL ELSE TRIM(delinquency_status) END AS delinquency_status,
    CAST(CASE WHEN TRIM(loan_age) IN ('') THEN NULL ELSE TRIM(loan_age) END AS INT) AS loan_age,
    CAST(CASE WHEN TRIM(remaining_months) IN ('') THEN NULL ELSE TRIM(remaining_months) END AS INT) AS remaining_months,
    CASE WHEN TRIM(defect_settlement_date) IN ('') THEN NULL ELSE TRIM(defect_settlement_date) END AS defect_settlement_date,
    CASE WHEN TRIM(modification_flag) IN ('') THEN NULL ELSE TRIM(modification_flag) END AS modification_flag,
    CASE WHEN TRIM(zero_balance_code) IN ('') THEN NULL ELSE TRIM(zero_balance_code) END AS zero_balance_code,
    CASE WHEN TRIM(zero_balance_date) IN ('') THEN NULL ELSE TRIM(zero_balance_date) END AS zero_balance_date,
    CAST(CASE WHEN TRIM(current_interest_rate) IN ('') THEN NULL ELSE TRIM(current_interest_rate) END AS DECIMAL(20, 4)) AS current_interest_rate,
    CAST(CASE WHEN TRIM(non_interest_bearing_upb) IN ('') THEN NULL ELSE TRIM(non_interest_bearing_upb) END AS DECIMAL(20, 4)) AS non_interest_bearing_upb,
    CASE WHEN TRIM(ddlpi) IN ('') THEN NULL ELSE TRIM(ddlpi) END AS ddlpi,
    CAST(CASE WHEN TRIM(mi_recoveries) IN ('') THEN NULL ELSE TRIM(mi_recoveries) END AS DECIMAL(20, 4)) AS mi_recoveries,
    CAST(CASE WHEN TRIM(net_sales_proceeds) IN ('') THEN NULL ELSE TRIM(net_sales_proceeds) END AS DECIMAL(20, 4)) AS net_sales_proceeds,
    CAST(CASE WHEN TRIM(non_mi_recoveries) IN ('') THEN NULL ELSE TRIM(non_mi_recoveries) END AS DECIMAL(20, 4)) AS non_mi_recoveries,
    CAST(CASE WHEN TRIM(total_expenses) IN ('') THEN NULL ELSE TRIM(total_expenses) END AS DECIMAL(20, 4)) AS total_expenses,
    CAST(CASE WHEN TRIM(legal_costs) IN ('') THEN NULL ELSE TRIM(legal_costs) END AS DECIMAL(20, 4)) AS legal_costs,
    CAST(CASE WHEN TRIM(maintenance_costs) IN ('') THEN NULL ELSE TRIM(maintenance_costs) END AS DECIMAL(20, 4)) AS maintenance_costs,
    CAST(CASE WHEN TRIM(taxes_insurance) IN ('') THEN NULL ELSE TRIM(taxes_insurance) END AS DECIMAL(20, 4)) AS taxes_insurance,
    CAST(CASE WHEN TRIM(misc_expenses) IN ('') THEN NULL ELSE TRIM(misc_expenses) END AS DECIMAL(20, 4)) AS misc_expenses,
    CAST(CASE WHEN TRIM(actual_loss) IN ('') THEN NULL ELSE TRIM(actual_loss) END AS DECIMAL(20, 4)) AS actual_loss,
    CAST(CASE WHEN TRIM(cumulative_modification_cost) IN ('') THEN NULL ELSE TRIM(cumulative_modification_cost) END AS DECIMAL(20, 4)) AS cumulative_modification_cost,
    CASE WHEN TRIM(interest_rate_step_flag) IN ('') THEN NULL ELSE TRIM(interest_rate_step_flag) END AS interest_rate_step_flag,
    CASE WHEN TRIM(payment_deferral_flag) IN ('') THEN NULL ELSE TRIM(payment_deferral_flag) END AS payment_deferral_flag,
    CAST(CASE WHEN TRIM(eltv) IN ('', '999') THEN NULL ELSE TRIM(eltv) END AS INT) AS eltv,
    CAST(CASE WHEN TRIM(zero_balance_removal_upb) IN ('') THEN NULL ELSE TRIM(zero_balance_removal_upb) END AS DECIMAL(20, 4)) AS zero_balance_removal_upb,
    CAST(CASE WHEN TRIM(delinquent_accrued_interest) IN ('') THEN NULL ELSE TRIM(delinquent_accrued_interest) END AS DECIMAL(20, 4)) AS delinquent_accrued_interest,
    CASE WHEN TRIM(disaster_delinquency_flag) IN ('') THEN NULL ELSE TRIM(disaster_delinquency_flag) END AS disaster_delinquency_flag,
    CASE WHEN TRIM(borrower_assistance_plan) IN ('') THEN NULL ELSE TRIM(borrower_assistance_plan) END AS borrower_assistance_plan,
    CAST(CASE WHEN TRIM(current_modification_cost) IN ('') THEN NULL ELSE TRIM(current_modification_cost) END AS DECIMAL(20, 4)) AS current_modification_cost,
    CAST(CASE WHEN TRIM(interest_bearing_upb) IN ('') THEN NULL ELSE TRIM(interest_bearing_upb) END AS DECIMAL(20, 4)) AS interest_bearing_upb,
    CASE WHEN TRIM(mi_cancellation_flag) IN ('', '7') THEN NULL ELSE TRIM(mi_cancellation_flag) END AS mi_cancellation_flag,
    CASE WHEN TRIM(servicer_name) IN ('') THEN NULL ELSE TRIM(servicer_name) END AS servicer_name,
    CAST(CASE WHEN TRIM(bankruptcy_cramdown_costs) IN ('') THEN NULL ELSE TRIM(bankruptcy_cramdown_costs) END AS DECIMAL(20, 4)) AS bankruptcy_cramdown_costs,
    load_date,
    record_source,
    source_file,
    period
FROM {{ source('quality', 'perf_clean') }}
